create table companies (id uuid primary key default gen_random_uuid(),name text not null,website text,domain text unique,country text,segment text,source text,status text not null default 'new',created_at timestamptz not null default now());
create table contacts (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,name text,role text,email text not null unique,verified boolean not null default false,unsubscribed boolean not null default false,consent_source text,created_at timestamptz not null default now());
create table company_profiles (company_id uuid primary key references companies(id) on delete cascade,summary text,products_they_print text,company_size text,fit_score int,interest_tags text[] not null default '{}',updated_at timestamptz not null default now());
create table products (sku text primary key,name text not null,material text,color text,price numeric(10,2),moq int,tags text[] not null default '{}',active boolean not null default true,updated_at timestamptz not null default now());
create table emails (id uuid primary key default gen_random_uuid(),contact_id uuid not null references contacts(id) on delete cascade,direction text not null check (direction in ('sent','received')),subject text,body text,thread_id text,message_id text,status text not null default 'draft',step int default 1,scheduled_for timestamptz,sent_at timestamptz,created_at timestamptz not null default now());
create table catalogs (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,product_skus text[] not null default '{}',pdf_url text,price_date date not null default current_date,created_at timestamptz not null default now());
create table pipeline (company_id uuid primary key references companies(id) on delete cascade,stage text not null default 'new',notes text,next_followup_at timestamptz,updated_at timestamptz not null default now());
create table events (id uuid primary key default gen_random_uuid(),company_id uuid references companies(id) on delete cascade,type text not null,data jsonb not null default '{}',created_at timestamptz not null default now());
create table suppression (email text primary key,reason text,created_at timestamptz not null default now());
create index on contacts (company_id);create index on emails (contact_id);create index on emails (status,scheduled_for);create index on events (company_id,created_at desc);
alter table companies enable row level security;alter table contacts enable row level security;alter table company_profiles enable row level security;alter table products enable row level security;alter table emails enable row level security;alter table catalogs enable row level security;alter table pipeline enable row level security;alter table events enable row level security;alter table suppression enable row level security;
